use std::collections::HashMap;
use std::io::{self, BufWriter, Write};

fn main() -> io::Result<()> {
    let path = std::env::args_os().nth(1).expect("usage: keyed-totals <file>");
    let data = std::fs::read(path)?;

    let mut lines: Vec<&[u8]> = data.split(|&b| b == b'\n').collect();
    if lines.last().is_some_and(|l| l.is_empty()) {
        lines.pop();
    }

    // None means the running total overflowed.
    let mut totals: HashMap<&[u8], Option<i64>> = HashMap::new();
    let mut iter = lines.into_iter();
    for line in iter.by_ref() {
        if line.is_empty() {
            break;
        }
        let Some(split) = line.iter().position(|&b| b == b' ') else {
            continue;
        };
        let (key, rest) = (&line[..split], &line[split + 1..]);
        let value = std::str::from_utf8(rest)
            .ok()
            .and_then(|s| s.trim().parse::<i64>().ok());
        let Some(value) = value else { continue };
        let entry = totals.entry(key).or_insert(Some(0));
        *entry = entry.and_then(|t| t.checked_add(value));
    }

    let mut out = BufWriter::new(io::stdout().lock());
    for key in iter {
        out.write_all(key)?;
        match totals.get(key) {
            None => out.write_all(b"=absent\n")?,
            Some(None) => out.write_all(b"=overflow\n")?,
            Some(Some(t)) => writeln!(out, "={t}")?,
        }
    }
    out.flush()
}
